import{_ as a,o as s,c as t,a2 as n}from"./chunks/framework.Io1M4tdt.js";const u=JSON.parse('{"title":"The show subcommand","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/show-subcommand/index.md","filePath":"explanation/show-subcommand.md","lastUpdated":1791765994000}'),i={name:"explanation/show-subcommand/index.md"};function o(r,e,p,l,h,c){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="the-show-subcommand" tabindex="-1">The show subcommand <a class="header-anchor" href="#the-show-subcommand" aria-label="Permalink to &quot;The show subcommand&quot;">​</a></h1><p>The main purpose of the <code>show</code> subcommand is to provide access to configuration data via scripts.</p><h2 id="basic-use" tabindex="-1">Basic use <a class="header-anchor" href="#basic-use" aria-label="Permalink to &quot;Basic use&quot;">​</a></h2><p>The configuration object is a <code>dict</code> containing nested data structures. The arguments and options of this command relate to extracting data from the configuration object and presenting the extracted data.</p><h2 id="specifying-the-output-data" tabindex="-1">Specifying the output data <a class="header-anchor" href="#specifying-the-output-data" aria-label="Permalink to &quot;Specifying the output data&quot;">​</a></h2><p>The positional arguments determine the data shown. If nothing or <code>all</code> is passed, the entire configuration is shown.</p><p>Positional arguments are specified using a format like <a href="https://docs.djangoproject.com/en/5.0/ref/templates/language/#variables" target="_blank" rel="noreferrer">Django variable resolution</a>.</p><p>Examples:</p><ul><li><code>a.b</code> specifies the &quot;b&quot; key in the nested dictionaries: <code>{&quot;a&quot;: {&quot;b&quot;: &quot;value&quot;}}</code></li><li><code>a.3</code> specifies the 4th item (the first is 0) of the list at key &quot;a&quot;: <code>{&quot;a&quot;: [&quot;no&quot;, &quot;nay&quot;, &quot;nyet&quot;, &quot;value&quot;]}</code></li></ul><h2 id="specifying-the-output-format" tabindex="-1">Specifying the output format <a class="header-anchor" href="#specifying-the-output-format" aria-label="Permalink to &quot;Specifying the output format&quot;">​</a></h2><p>If only one positional argument is passed, the default format only shows its value. If no positional arguments, several positional arguments, or <code>all</code> is passed, the output from <a href="https://docs.python.org/3.12/library/pprint.html#pprint.pprint" target="_blank" rel="noreferrer"><code>pprint.pprint</code></a> is shown.</p><p>This makes getting the current version easy:</p><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ bump-my-version show current_version</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.0.1</span></span></code></pre></div><p>You can request the output be formatted as YAML or JSON:</p><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ bump-my-version show --format yaml current_version</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">current_version: &quot;1.0.1&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ bump-my-version show --format json current_version</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;current_version&quot;: &quot;1.0.1&quot;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">}</span></span></code></pre></div><h2 id="including-the-incremented-version-before-bumping" tabindex="-1">Including the incremented version before bumping <a class="header-anchor" href="#including-the-incremented-version-before-bumping" aria-label="Permalink to &quot;Including the incremented version before bumping&quot;">​</a></h2><p>Your workflow might want to know the new version before you actually do the bumping. The <code>--increment</code> or <code>-i</code> option accepts a version part to bump and adds a <code>new_version</code> key into the configuration.</p><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ bump-my-version show --increment patch new_version</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.0.2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ bump-my-version show --increment minor new_version</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.1.0</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ bump-my-version show --increment major new_version</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2.0.0</span></span></code></pre></div>`,18)])])}const m=a(i,[["render",o]]);export{u as __pageData,m as default};
